=== models.py ===
from dataclasses import dataclass
from datetime import date
from decimal import Decimal
@dataclass(frozen=True)
class Entry:
    account: str
    amount: Decimal
    day: date
    status: str = 'posted'
    currency: str = 'USD'
=== parser.py ===
import csv,io,re
from datetime import date
from decimal import Decimal
from .models import Entry
_CURRENCY_RE = re.compile(r'^[A-Za-z]{3}$')
def _normalize_currency(raw):
    if raw is None:
        return 'USD'
    code = str(raw).strip()
    if not code:
        return 'USD'
    if not _CURRENCY_RE.match(code):
        raise ValueError(f'invalid currency code: {code!r}')
    return code.upper()
def parse_csv(text):
    return [Entry(row['account'],Decimal(row['amount']),date.fromisoformat(row['day']),row.get('status') or 'posted',_normalize_currency(row.get('currency'))) for row in csv.DictReader(io.StringIO(text))]
=== summary.py ===
from datetime import date
from decimal import Decimal
def total(entries):
    return sum((e.amount for e in entries),Decimal('0'))
def _validate_bounds(start, end):
    if start is not None and end is not None and start > end:
        raise ValueError(f'invalid date range: {start} after {end}')
def _filter(entries, start, end):
    out = []
    for e in entries:
        if start is not None and e.day < start:
            continue
        if end is not None and e.day > end:
            continue
        out.append(e)
    return out
def totals_by_currency(entries, start=None, end=None, include_pending=False):
    _validate_bounds(start, end)
    selected = [e for e in _filter(entries, start, end) if include_pending or e.status == 'posted']
    by_currency = {}
    for e in selected:
        by_currency[e.currency] = by_currency.get(e.currency, Decimal('0')) + e.amount
    return by_currency
=== cli.py ===
import json
from .parser import parse_csv
from .summary import total, totals_by_currency
def render_report(text, *, by_currency=False, start=None, end=None):
    if not by_currency:
        return json.dumps({'total':format(total(parse_csv(text)),'.2f')},sort_keys=True)
    entries = parse_csv(text)
    grouped = totals_by_currency(entries, start=start, end=end, include_pending=False)
    return json.dumps({'totals':{c:format(v,'.2f') for c,v in sorted(grouped.items())}},sort_keys=True)

